'use strict';
const $ = id => document.getElementById(id);
const send = message => chrome.runtime.sendMessage(message);
function validate(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Request must be a JSON object.');
  if (value.version !== 1 || value.operation !== 'tool.propose') throw new Error('Unsupported protocol version or operation.');
  // Request IDs are generated by the extension; the AI/page cannot choose a task or workspace.
  if (!['list_dir','read_file','grep','glob','write_file','edit_file','move_file','delete_file'].includes(value.tool)) throw new Error('Unsupported tool.');
  if (!value.args || typeof value.args !== 'object' || Array.isArray(value.args)) throw new Error('args must be an object.');
}
async function refresh() {
  $('status-title').textContent = 'Checking connection…';
  const response = await send({ type: 'NEELIMA_GET_STATUS' });
  const connected = Boolean(response?.nativeHostConnected && !response?.connectionError);
  $('status-dot').classList.toggle('online', connected);
  $('status-title').textContent = connected ? 'Native host connected' : 'Neelima not connected';
  $('status-detail').textContent = connected ? 'Requests are routed to Neelima. The desktop backend remains responsible for permissions and execution.' : `The extension cannot reach the local Neelima host yet. ${response?.connectionError || 'Install and register the Neelima native host first.'}`;
  $('bridge-state').textContent = connected ? 'Connected' : 'Unavailable';
  const s = response?.settings || { permissionMode: 'approve_each_write', enabledSites: [], genericSites: [], paused: false };
  $('mode-state').textContent = s.permissionMode === 'workspace_auto_write' ? 'Automatic workspace writes*' : 'Approve each modification';
  $('sites-state').textContent = [...(s.enabledSites || []), ...(s.genericSites?.length ? [`${s.genericSites.length} custom`] : [])].join(', ') || 'None';
  $('paused').checked = Boolean(s.paused);
}
$('refresh').addEventListener('click', () => void refresh());
$('open-options').addEventListener('click', () => chrome.runtime.openOptionsPage());
$('paused').addEventListener('change', async event => {
  const current = await send({ type: 'NEELIMA_GET_SETTINGS' });
  await send({ type: 'NEELIMA_SAVE_SETTINGS', settings: { ...current.settings, paused: event.target.checked } });
  await refresh();
});
$('enable-generic').addEventListener('click', async () => {
  const result = $('generic-result');
  try {
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    if (!tab?.id || !tab.url) throw new Error('No active tab found.');
    const response = await send({ type: 'NEELIMA_ENABLE_GENERIC_ON_TAB', tabId: tab.id, url: tab.url });
    if (!response?.ok) throw new Error(response?.error || 'Could not inject generic adapter.');
    result.textContent = 'Generic adapter injected. Look for a Neelima tool-call block.'; result.className = 'hint success';
  } catch (e) { result.textContent = e.message || 'Could not enable adapter.'; result.className = 'hint error'; }
});
$('validate-request').addEventListener('click', async () => {
  const result = $('manual-result');
  try {
    const proposal = JSON.parse($('manual-request').value);
    validate(proposal);
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    if (!tab?.id || !tab.url) throw new Error('No active tab found.');
    const response = await send({ type: 'NEELIMA_MANUAL_PROPOSE', proposal, tabId: tab.id, url: tab.url });
    if (!response?.ok) throw new Error(response?.error || 'Neelima rejected the request.');
    result.textContent = `Sent to Neelima: ${response.status || 'accepted'}. ${response.message || ''}`;
    result.className = 'hint success';
  } catch (e) { result.textContent = e.message || 'Invalid request.'; result.className = 'hint error'; }
});
void refresh();
